where problem_id in (
  'two-sum',
  'valid-palindrome',
  'valid-parentheses',
  'maximum-subarray',
  'container-with-most-water',
  'longest-substring-without-repeating-characters',
  'climbing-stairs',
  'trapping-rain-water',
  'binary-search',
  'coin-change',
  'valid-anagram',
  'reverse-linked-list',
  'binary-tree-inorder-traversal',
  'maximum-depth-of-binary-tree',
  'intersection-of-two-arrays',
  'fibonacci-number',
  'single-number',
  'move-zeroes',
  'plus-one',
  'contains-duplicate',
);


-- Sanity checks
